import presets from "../generated/backgrounds.json";
import type { BackgroundColor, Language } from "../types/settings";

// Bundled pictures, generated by `bun run backgrounds` (scripts/backgrounds.ts).
// Each preset has a light and/or a dark variant; index.css (via
// generated/backgrounds.css) shows the one matching the theme.
export type BackgroundPreset = {
  id: string;
  name: Partial<Record<Language, string>> & { en: string };
  light?: string;
  dark?: string;
};

export const backgroundPresets: readonly BackgroundPreset[] = presets;

export const backgroundImages: readonly string[] = presets.map(
  (preset) => preset.id,
);

// Must match the `data-bg-color` rules in index.css.
export const backgroundColors: readonly BackgroundColor[] = [
  "slate",
  "sand",
  "sage",
  "sky",
  "teal",
  "lavender",
  "rose",
  "peach",
];

// The thumbnail of each variant; a preset without one falls back to the other.
export function backgroundThumbUrls(preset: BackgroundPreset): {
  light: string;
  dark: string;
} {
  const light = preset.light ? "light" : "dark";
  const dark = preset.dark ? "dark" : "light";
  return {
    light: `/backgrounds/${preset.id}-${light}-thumb.webp`,
    dark: `/backgrounds/${preset.id}-${dark}-thumb.webp`,
  };
}

export function backgroundName(preset: BackgroundPreset, language: Language): string {
  return preset.name[language] ?? preset.name.en;
}
